<section class="store-hero"><div><p class="eyebrow">Order online</p><h1><?= e($storeName) ?></h1><p class="muted">Browse the current selection, build your cart, and submit your order securely.</p></div><p class="muted">Availability and pricing are confirmed from the live catalog.</p></section>
<?php if (!$products): ?><div class="empty-state"><h2>Nothing is available just yet</h2><p class="muted">Please check back soon.</p></div><?php else: ?><div class="product-grid"><?php foreach ($products as $product): ?><article class="product-card"><a href="<?= e_attr($basePath) ?>/store/<?= e_attr($product['slug']) ?>" aria-label="View <?= e_attr($product['name']) ?>"><?php if ($product['image_url']): ?><img class="product-image" src="<?= e_attr($product['image_url']) ?>" alt=""><?php else: ?><div class="product-image empty">Freshly prepared for you</div><?php endif; ?></a><div class="product-body"><p class="eyebrow"><?= e($product['sku']) ?></p><h2><a href="<?= e_attr($basePath) ?>/store/<?= e_attr($product['slug']) ?>"><?= e($product['name']) ?></a></h2><p class="muted"><?= e($product['description']) ?></p><p class="price"><?= e($product['currency']) ?> $<?= number_format((int) $product['price_minor'] / 100, 2) ?></p><?php if ((int)$product['track_inventory'] && (int)$product['stock_quantity'] < 1): ?><span class="muted">Currently unavailable</span><?php else: ?><form method="post" action="<?= e_attr($basePath) ?>/cart/add" class="product-actions"><?= $csrf->field() ?><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><label><span class="sr-only">Quantity</span><input type="number" name="quantity" value="1" min="1" max="99" aria-label="Quantity for <?= e_attr($product['name']) ?>"></label><button class="btn">Add to cart</button></form><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?>
